css:
@media all {
   div .printedby {
       position: fixed;
       bottom: 0;
       text-align: right;
       font-size: xx-small;
       width: 100% !important;
   }
}

table {
	table-layout: fixed;
	width: 100%;
}

th, td {
	font-size: 11px;
	padding: 6px;
	word-wrap: break-word;
	white-space: normal;
}

.text-right {
	text-align: right;
}
